        return bd.doubleValue();
    }

    public static class ValidationException extends RuntimeException {
        private final String codigo;

        public ValidationException(String codigo) {
            super(codigo);
            this.codigo = codigo;
        }

        public String getCodigo() {
            return codigo;
        }
    }
}
